const config = {
  "previewFeatures": [],
  "clientVersion": "7.4.1",
  "engineVersion": "55ae170b1ced7fc6ed07a15f110549408c501bb3",
  "activeProvider": "postgresql",
  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// Roles for RBAC (Owner = vendeur créateur du tenant, OPS = accès console ops sans tenant)\nenum Role {\n  OWNER\n  MANAGER\n  VENDEUR\n  AGENT\n  OPS\n}\n\nmodel Tenant {\n  id                    String    @id @default(cuid())\n  name                  String\n  // Meta WhatsApp Cloud API (Story 10.1)\n  metaPhoneNumberId     String?   @unique @map(\"meta_phone_number_id\")\n  metaWabaId            String?   @map(\"meta_waba_id\")\n  metaAccessToken       String?   @map(\"meta_access_token\") // TODO: chiffrer at-rest (secret API sensible)\n  requireDeposit        Boolean   @default(false) @map(\"require_deposit\") // Story 4.5: acompte activé → TTL locked, demande preuve\n  createdAt             DateTime  @default(now()) @map(\"created_at\")\n  updatedAt             DateTime  @updatedAt @map(\"updated_at\")\n  // Subscription (Story 7A.2)\n  subscriptionPlan      String    @default(\"free\") @map(\"subscription_plan\")\n  // \"free\" | \"starter\" | \"pro\"\n  subscriptionStatus    String    @default(\"active\") @map(\"subscription_status\")\n  // \"active\" | \"attention\" | \"non_renewing\" | \"expired\" | \"cancelled\"\n  subscriptionExpiresAt DateTime? @map(\"subscription_expires_at\")\n  // null = Free (pas d'expiration) ; set à +30j après paiement pour Starter/Pro\n  cycleStartedAt        DateTime? @map(\"cycle_started_at\")\n  // Début du cycle courant (pour compter l'usage). null = Free\n\n  // Paystack references\n  paystackCustomerCode      String? @unique @map(\"paystack_customer_code\")\n  paystackSubscriptionCode  String? @unique @map(\"paystack_subscription_code\")\n  paystackEmailToken        String? @map(\"paystack_email_token\")\n  paystackAuthorizationCode String? @map(\"paystack_authorization_code\")\n\n  // Entitlements — quotas numériques\n  maxConfirmedOrdersPerMonth Int @default(50) @map(\"max_confirmed_orders_per_month\")\n  maxProofsPerMonth          Int @default(20) @map(\"max_proofs_per_month\") // -1 = illimité\n  maxAgents                  Int @default(0) @map(\"max_agents\") // 0 = pas d'agents\n  overagePerOrderCents       Int @default(0) @map(\"overage_per_order_cents\") // 0 = blocage (Free)\n\n  // Entitlements — feature flags\n  hasExportCsv               Boolean @default(false) @map(\"has_export_csv\")\n  hasAdvancedExports         Boolean @default(false) @map(\"has_advanced_exports\")\n  hasNotificationsOutside24h Boolean @default(false) @map(\"has_notifications_outside_24h\")\n  hasDepositRecommended      Boolean @default(false) @map(\"has_deposit_recommended\")\n  hasAdvancedFilters         Boolean @default(false) @map(\"has_advanced_filters\")\n  hasPrioritySupport         Boolean @default(false) @map(\"has_priority_support\")\n  showBranding               Boolean @default(true) @map(\"show_branding\") // Free = true\n  showUpgradeBanner          Boolean @default(true) @map(\"show_upgrade_banner\") // Free = true\n\n  // FAQ bot — réponses configurables par le vendeur (Phase 5.3)\n  faqDelivery     String? @map(\"faq_delivery\") @db.Text\n  faqPayment      String? @map(\"faq_payment\") @db.Text\n  faqLocation     String? @map(\"faq_location\") @db.Text\n  faqAvailability String? @map(\"faq_availability\") @db.Text\n\n  users                User[]\n  conversationStates   ConversationState[]\n  categoryPrices       CategoryPrice[]\n  deliveryZones        DeliveryZone[]\n  deliveryFeeCommune   DeliveryFeeCommune[]\n  invitations          Invitation[]\n  messagesIn           MessageIn[]\n  messagesOut          MessageOut[]\n  sellerPhones         SellerPhone[]\n  eventLogs            EventLog[]\n  deadLetterJobs       DeadLetterJob[]\n  optOuts              OptOut[]\n  liveSessions         LiveSession[]\n  liveItems            LiveItem[]\n  catalogueItems       CatalogueItem[]\n  reservations         Reservation[]\n  waitlists            Waitlist[]\n  orders               Order[]\n  paymentProofs        PaymentProof[]\n  subscriptionPayments SubscriptionPayment[]\n\n  @@map(\"tenants\")\n}\n\n// Invitation envoyée par un Owner/Manager pour ajouter un agent au tenant (story 1-7)\nmodel Invitation {\n  id         String    @id @default(cuid())\n  tenantId   String    @map(\"tenant_id\")\n  tenant     Tenant    @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  email      String\n  role       Role      @default(AGENT)\n  tokenHash  String    @unique @map(\"token_hash\") // Hash SHA-256 du token\n  expiresAt  DateTime  @map(\"expires_at\")\n  consumedAt DateTime? @map(\"consumed_at\")\n  createdAt  DateTime  @default(now()) @map(\"created_at\")\n\n  @@index([tenantId])\n  @@index([tokenHash])\n  // Note: Contrainte unique partielle (tenantId, email) où consumedAt IS NULL\n  // sera créée via migration SQL car Prisma ne supporte pas directement les contraintes partielles\n  @@map(\"invitations\")\n}\n\n// Zone regroupant plusieurs communes (ex. Abidjan, Intérieur du pays)\nmodel DeliveryZone {\n  id        String                @id @default(cuid())\n  tenantId  String                @map(\"tenant_id\")\n  tenant    Tenant                @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  name      String // ex. \"Abidjan\", \"Intérieur du pays\"\n  amount    Int                   @map(\"amount_cents\")\n  communes  DeliveryZoneCommune[]\n  createdAt DateTime              @default(now()) @map(\"created_at\")\n  updatedAt DateTime              @updatedAt @map(\"updated_at\")\n\n  @@index([tenantId])\n  @@map(\"delivery_zones\")\n}\n\n// Communes appartenant à une zone (identifiées par nom, pas de code en Côte d'Ivoire)\nmodel DeliveryZoneCommune {\n  id          String       @id @default(cuid())\n  zoneId      String       @map(\"zone_id\")\n  zone        DeliveryZone @relation(fields: [zoneId], references: [id], onDelete: Cascade)\n  communeName String       @map(\"commune_name\") // ex. \"Cocody\", \"Marcory\", \"Yopougon\"\n\n  @@unique([zoneId, communeName])\n  @@index([zoneId])\n  @@map(\"delivery_zone_communes\")\n}\n\n// Prix par commune (hors zone ou surcharge), identifié par nom\nmodel DeliveryFeeCommune {\n  id          String   @id @default(cuid())\n  tenantId    String   @map(\"tenant_id\")\n  tenant      Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  communeName String   @map(\"commune_name\") // ex. \"Cocody\", \"Bouaké\"\n  amount      Int      @map(\"amount_cents\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  @@unique([tenantId, communeName])\n  @@index([tenantId])\n  @@map(\"delivery_fee_communes\")\n}\n\nmodel User {\n  id            String    @id @default(cuid())\n  tenantId      String?   @map(\"tenant_id\") // Nullable : null pour les users OPS (pas de tenant)\n  tenant        Tenant?   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  email         String    @unique\n  emailVerified DateTime? @map(\"email_verified\")\n  name          String?\n  image         String?\n  passwordHash  String?   @map(\"password_hash\")\n  role          Role      @default(OWNER)\n  tokenVersion  Int       @default(0) @map(\"token_version\") // Révocation JWT : incrémenter pour invalider toutes les sessions actives\n  createdAt     DateTime  @default(now()) @map(\"created_at\")\n  updatedAt     DateTime  @updatedAt @map(\"updated_at\")\n  accounts      Account[]\n  sessions      Session[]\n\n  @@index([tenantId])\n  @@map(\"users\")\n}\n\n// NextAuth / Auth.js Prisma adapter models\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String  @map(\"user_id\")\n  type              String\n  provider          String\n  providerAccountId String  @map(\"provider_account_id\")\n  refresh_token     String? @db.Text\n  access_token      String? @db.Text\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String? @db.Text\n  session_state     String?\n  user              User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n  @@map(\"accounts\")\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique @map(\"session_token\")\n  userId       String   @map(\"user_id\")\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"sessions\")\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String\n  expires    DateTime\n\n  @@unique([identifier, token])\n  @@map(\"verification_tokens\")\n}\n\nmodel CategoryPrice {\n  id             String   @id @default(cuid())\n  tenantId       String   @map(\"tenant_id\")\n  tenant         Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  categoryLetter String   @map(\"category_letter\") // code libre (ex. A, AB, Premium)\n  amount         Int      @map(\"amount_cents\")\n  description    String?  @db.Text\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n  updatedAt      DateTime @updatedAt @map(\"updated_at\")\n\n  @@unique([tenantId, categoryLetter])\n  @@index([tenantId])\n  @@map(\"category_prices\")\n}\n\n// Message entrant WhatsApp (webhook) - Story 2.1\nmodel MessageIn {\n  id                String   @id @default(cuid())\n  tenantId          String?  @map(\"tenant_id\") // nullable si tenant non résolu\n  tenant            Tenant?  @relation(fields: [tenantId], references: [id], onDelete: SetNull)\n  providerMessageId String   @map(\"provider_message_id\") // ex. wamid Meta\n  from              String // numéro WhatsApp expéditeur\n  body              String   @db.Text\n  mediaUrl          String?  @map(\"media_url\")\n  correlationId     String   @map(\"correlation_id\") // UUID ou message_sid pour traçabilité\n  createdAt         DateTime @default(now()) @map(\"created_at\")\n\n  @@unique([tenantId, providerMessageId])\n  @@index([tenantId, providerMessageId])\n  @@index([tenantId])\n  @@map(\"messages_in\")\n}\n\n// Numéro de téléphone vendeur par tenant (Story 2.2)\n// Permet de distinguer les messages vendeur des messages client\nmodel SellerPhone {\n  id          String   @id @default(cuid())\n  tenantId    String   @map(\"tenant_id\")\n  tenant      Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  phoneNumber String   @map(\"phone_number\") // Format E.164 normalisé (ex. +33612345678)\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n\n  @@unique([tenantId, phoneNumber])\n  @@index([tenantId])\n  @@map(\"seller_phones\")\n}\n\n// Event Log pour traçabilité des événements critiques (Story 2.3)\n// Architecture §9: Event Log avec correlationId pour diagnostic bout en bout\n// Architecture §426-430: event_type verbe/nom explicite, correlation_id propagé, payload JSON structuré sans PII\nmodel EventLog {\n  id            String   @id @default(cuid())\n  tenantId      String   @map(\"tenant_id\") // NOT NULL: isolation tenant stricte\n  tenant        Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  eventType     String   @map(\"event_type\") // webhook_received, message_sent, idempotent_ignored\n  entityType    String   @map(\"entity_type\") // message_in, message_out, etc.\n  entityId      String?  @map(\"entity_id\") // ID de l'entité concernée (nullable si pas d'entité)\n  correlationId String   @map(\"correlation_id\") // UUID ou message_sid pour traçabilité bout en bout\n  actorType     String   @map(\"actor_type\") // system, seller, client\n  payload       Json // JSON structuré, pas de PII (Architecture §430)\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n\n  @@index([tenantId, correlationId]) // Lookup rapide par flux\n  @@index([tenantId, eventType, createdAt]) // Filtrage par type et date\n  @@index([tenantId])\n  @@map(\"event_log\")\n}\n\n// Opt-out STOP par tenant (Story 2.5) - scope tenant, isolation stricte\nmodel OptOut {\n  id          String   @id @default(cuid())\n  tenantId    String   @map(\"tenant_id\") // NOT NULL: isolation tenant stricte\n  tenant      Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  phoneNumber String   @map(\"phone_number\") // Format E.164 normalisé\n  optedOutAt  DateTime @default(now()) @map(\"opted_out_at\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  @@unique([tenantId, phoneNumber]) // index unique implicite pour lookup rapide\n  @@map(\"opt_outs\")\n}\n\n// Message sortant via outbox (Story 2.4)\n// Architecture §4.5: Outbound messaging via outbox + retries + DLQ\n// Tout envoi sortant écrit d'abord dans MessageOut (outbox) avec statut pending\nmodel MessageOut {\n  id                 String    @id @default(cuid())\n  tenantId           String    @map(\"tenant_id\") // NOT NULL: isolation tenant stricte\n  tenant             Tenant    @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  to                 String // destinataire (format E.164 normalisé)\n  body               String    @db.Text\n  mediaUrl           String?   @map(\"media_url\") @db.Text // Story 9.4: URL média (photo article) pour MMS WhatsApp\n  interactivePayload Json?     @map(\"interactive_payload\") // Payload boutons/liste pour messages interactifs WhatsApp\n  status             String // pending | sending | sent | failed | blocked (STOP)\n  attempts           Int       @default(0)\n  nextAttemptAt      DateTime? @map(\"next_attempt_at\")\n  lastError          String?   @map(\"last_error\") @db.Text\n  correlationId      String    @map(\"correlation_id\") // UUID ou message_sid pour traçabilité\n  providerMessageId  String?   @map(\"provider_message_id\") // wamid Meta après envoi réussi\n  createdAt          DateTime  @default(now()) @map(\"created_at\")\n  updatedAt          DateTime  @updatedAt @map(\"updated_at\")\n\n  @@unique([tenantId, correlationId, to]) // Anti-doublon : même message pas écrit deux fois (optionnel Story 2.4)\n  @@index([tenantId, status]) // Lookup rapide des messages pending\n  @@index([tenantId, correlationId]) // Traçabilité par correlationId\n  @@index([tenantId])\n  @@map(\"messages_out\")\n}\n\n// Session live par tenant - création/fermeture auto (Story 2.6)\n// Une seule session active par tenant à la fois (contrainte applicative)\nenum LiveSessionStatus {\n  active\n  closed\n}\n\nmodel LiveSession {\n  id             String            @id @default(cuid())\n  tenantId       String            @map(\"tenant_id\")\n  tenant         Tenant            @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  status         LiveSessionStatus @default(active)\n  lastActivityAt DateTime          @map(\"last_activity_at\")\n  createdAt      DateTime          @default(now()) @map(\"created_at\")\n  updatedAt      DateTime          @updatedAt @map(\"updated_at\")\n  liveItems      LiveItem[]\n  reservations   Reservation[]\n\n  @@index([tenantId, status])\n  @@map(\"live_sessions\")\n}\n\n// Item live par session — unicité (tenant_id, live_session_id, code) (Story 3.2)\n// Story 3.4: availableQty / reservedQty pour stock préparé ; mediaStorageKey pour photo optionnelle\nmodel LiveItem {\n  id              String      @id @default(cuid())\n  tenantId        String      @map(\"tenant_id\")\n  tenant          Tenant      @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  liveSessionId   String      @map(\"live_session_id\")\n  liveSession     LiveSession @relation(fields: [liveSessionId], references: [id], onDelete: Cascade)\n  code            String // normalisé trim + uppercase\n  amount          Int?        @map(\"amount_cents\") // optionnel, dérivé grille (Story 3.1)\n  quantity        Int         @default(1) // total (availableQty + reservedQty) pour affichage\n  availableQty    Int         @default(0) @map(\"available_qty\") // stock préparé (Story 3.4)\n  reservedQty     Int         @default(0) @map(\"reserved_qty\") // réservé, décrément à confirmation (Story 3.6)\n  mediaStorageKey String?     @map(\"media_storage_key\") // clé R2 pour photo optionnelle (Story 3.4)\n  createdAt       DateTime    @default(now()) @map(\"created_at\")\n  updatedAt       DateTime    @updatedAt @map(\"updated_at\")\n\n  reservations Reservation[]\n\n  @@unique([tenantId, liveSessionId, code])\n  @@index([tenantId])\n  @@index([liveSessionId])\n  @@map(\"live_items\")\n}\n\n// Story 8.1: Article catalogue persistant — seule source d'articles commandables\n// Unicité (tenantId, code) — le code = étiquette persistante de l'article\nmodel CatalogueItem {\n  id              String              @id @default(cuid())\n  tenantId        String              @map(\"tenant_id\")\n  tenant          Tenant              @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  code            String // normalisé trim + uppercase\n  amount          Int?                @map(\"amount_cents\")\n  quantity        Int                 @default(1)\n  availableQty    Int                 @default(1) @map(\"available_qty\")\n  reservedQty     Int                 @default(0) @map(\"reserved_qty\")\n  mediaStorageKey String?             @map(\"media_storage_key\")\n  origin          CatalogueItemOrigin @default(dashboard)\n  createdInLive   Boolean             @default(false) @map(\"created_in_live\")\n  createdAt       DateTime            @default(now()) @map(\"created_at\")\n  updatedAt       DateTime            @updatedAt @map(\"updated_at\")\n\n  reservations Reservation[]\n  waitlist     Waitlist[]\n\n  @@unique([tenantId, code])\n  @@index([tenantId])\n  @@map(\"catalogue_items\")\n}\n\nenum CatalogueItemOrigin {\n  live\n  seller_whatsapp\n  dashboard\n}\n\n// Réservation client par article (Story 4.1)\n// Story 8.1: idempotence via partial unique indexes (migration SQL)\nenum ReservationStatus {\n  reserved\n  address_collected\n  confirmed\n  expired\n}\n\nmodel Reservation {\n  id              String            @id @default(cuid())\n  tenantId        String            @map(\"tenant_id\")\n  tenant          Tenant            @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  liveSessionId   String?           @map(\"live_session_id\")\n  liveSession     LiveSession?      @relation(fields: [liveSessionId], references: [id], onDelete: Cascade)\n  liveItemId      String?           @map(\"live_item_id\")\n  liveItem        LiveItem?         @relation(fields: [liveItemId], references: [id], onDelete: Cascade)\n  catalogueItemId String?           @map(\"catalogue_item_id\")\n  catalogueItem   CatalogueItem?    @relation(fields: [catalogueItemId], references: [id], onDelete: Cascade)\n  clientPhone     String            @map(\"client_phone\") // E.164 normalisé\n  status          ReservationStatus @default(reserved)\n  address         String?           @db.Text\n  expiresAt       DateTime?         @map(\"expires_at\")\n  reminderSentAt  DateTime?         @map(\"reminder_sent_at\") // Story 4.4: rappel T-2 min envoyé une seule fois\n  correlationId   String            @map(\"correlation_id\")\n  createdAt       DateTime          @default(now()) @map(\"created_at\")\n  updatedAt       DateTime          @updatedAt @map(\"updated_at\")\n  order           Order?\n\n  // Note: partial unique indexes are defined in the migration SQL (Prisma doesn't support partial indexes)\n  @@index([tenantId, liveSessionId, clientPhone])\n  @@index([tenantId])\n  @@index([liveItemId, liveSessionId])\n  @@index([catalogueItemId])\n  @@map(\"reservations\")\n}\n\n// État de conversation par client (Phase 5.1) — handoff + contexte bot\nmodel ConversationState {\n  id        String   @id @default(cuid())\n  tenantId  String   @map(\"tenant_id\")\n  tenant    Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  phone     String\n  handedOff Boolean  @default(false) @map(\"handed_off\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@unique([tenantId, phone])\n  @@index([tenantId])\n  @@map(\"conversation_states\")\n}\n\n// Commande créée à la confirmation (OUI) — Story 4.5\nenum OrderStatus {\n  confirmed\n  confirmed_pending_deposit\n  preparing // prépa (Story 6.3)\n  in_delivery // livraison (Story 6.3)\n  delivered\n  cancelled\n}\n\nenum DepositStatus {\n  no_deposit\n  deposit_pending\n  deposit_approved\n  deposit_rejected\n}\n\nmodel Order {\n  id               String         @id @default(cuid())\n  tenantId         String         @map(\"tenant_id\")\n  tenant           Tenant         @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  reservationId    String         @unique @map(\"reservation_id\")\n  reservation      Reservation    @relation(fields: [reservationId], references: [id], onDelete: Cascade)\n  orderNumber      String         @map(\"order_number\") // SS-XXXX (SnapSell)\n  status           OrderStatus\n  depositStatus    DepositStatus  @map(\"deposit_status\")\n  depositExpiresAt DateTime?      @map(\"deposit_expires_at\")\n  createdAt        DateTime       @default(now()) @map(\"created_at\")\n  updatedAt        DateTime       @updatedAt @map(\"updated_at\")\n  paymentProofs    PaymentProof[]\n\n  @@unique([tenantId, orderNumber])\n  @@index([tenantId])\n  @@index([reservationId])\n  @@map(\"orders\")\n}\n\n// Story 5.3: Preuve d'acompte (image ou texte) liée à une commande\nenum PaymentProofStatus {\n  pending\n  approved\n  rejected\n}\n\nmodel PaymentProof {\n  id              String             @id @default(cuid())\n  orderId         String             @map(\"order_id\")\n  order           Order              @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  tenantId        String             @map(\"tenant_id\")\n  tenant          Tenant             @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  mediaStorageKey String?            @map(\"media_storage_key\") // clé R2 (signed URL dérivée)\n  textPayload     String?            @map(\"text_payload\") @db.Text // preuve texte\n  status          PaymentProofStatus @default(pending)\n  reviewedAt      DateTime?          @map(\"reviewed_at\")\n  correlationId   String             @map(\"correlation_id\")\n  createdAt       DateTime           @default(now()) @map(\"created_at\")\n  updatedAt       DateTime           @updatedAt @map(\"updated_at\")\n\n  @@index([tenantId])\n  @@index([orderId])\n  @@index([tenantId, status])\n  @@map(\"payment_proofs\")\n}\n\n// File d'attente par article/session (Story 4.3, 9.1)\n// position = ordre d'arrivée (max+1 sous lock)\n// Story 9.1: catalogueItemId nullable, liveSessionId/liveItemId nullable\n// Unicité via partial unique indexes en SQL (Prisma ne supporte pas les index partiels)\nmodel Waitlist {\n  id              String         @id @default(cuid())\n  tenantId        String         @map(\"tenant_id\")\n  tenant          Tenant         @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  liveSessionId   String?        @map(\"live_session_id\")\n  liveItemId      String?        @map(\"live_item_id\")\n  catalogueItemId String?        @map(\"catalogue_item_id\")\n  catalogueItem   CatalogueItem? @relation(fields: [catalogueItemId], references: [id], onDelete: Cascade)\n  clientPhone     String         @map(\"client_phone\")\n  position        Int // ordre d'arrivée\n  correlationId   String         @map(\"correlation_id\")\n  createdAt       DateTime       @default(now()) @map(\"created_at\")\n\n  @@index([tenantId, liveSessionId, liveItemId])\n  @@index([liveItemId, liveSessionId])\n  @@index([catalogueItemId])\n  @@map(\"waitlist\")\n}\n\n// Dead Letter Queue pour messages échoués après N retries (Story 2.4)\n// Architecture §4.5: DLQ après échec répété pour traçabilité ops\nmodel DeadLetterJob {\n  id           String    @id @default(cuid())\n  tenantId     String    @map(\"tenant_id\") // NOT NULL: isolation tenant stricte\n  tenant       Tenant    @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  jobType      String    @map(\"job_type\") // ex. 'message_out'\n  payload      Json // Payload original (JSON)\n  errorMessage String?   @map(\"error_message\") @db.Text\n  errorStack   String?   @map(\"error_stack\") @db.Text\n  attempts     Int       @default(0)\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  resolvedAt   DateTime? @map(\"resolved_at\") // null si non résolu\n\n  @@index([tenantId, jobType, resolvedAt]) // Filtrage ops\n  @@index([tenantId])\n  @@map(\"dead_letter_jobs\")\n}\n\n// Story 7A.2: Historique paiements abonnement + overages\nmodel SubscriptionPayment {\n  id                String   @id @default(cuid())\n  tenantId          String   @map(\"tenant_id\")\n  tenant            Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  paystackReference String   @unique @map(\"paystack_reference\") // Idempotence\n  type              String // \"subscription\" | \"overage\"\n  plan              String? // \"starter\" | \"pro\" (null si overage seul)\n  amount            Int // Montant en FCFA\n  currency          String   @default(\"XOF\")\n  status            String // \"pending\" | \"success\" | \"failed\"\n  channel           String? // \"card\" | \"mobile_money\"\n  cardLast4         String?  @map(\"card_last4\")\n  overageDetails    Json?    @map(\"overage_details\")\n  // { ordersOverQuota: 12, ratePerOrder: 75, totalAmount: 900 }\n  metadata          Json?\n  createdAt         DateTime @default(now()) @map(\"created_at\")\n  updatedAt         DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([tenantId])\n  @@index([tenantId, type, status])\n  @@map(\"subscription_payments\")\n}\n"
}

